const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function getMigrationFiles() {
  // Read all files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      process.exit(1);
    }
    throw err;
  }

  // Filter to only .sql files and sort them alphabetically (which works well
  // for timestamp- or sequence-number-prefixed filenames)
  const sqlFiles = files
    .filter((file) => path.extname(file).toLowerCase() === '.sql')
    .sort();

  return sqlFiles;
}

function migrate() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. Applying: ${file}`);
  });

  console.log('\nAll migrations listed successfully.');
}

migrate();

