const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parses a .env-style file and returns an object of key/value pairs.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const env = {};

  content.split('\n').forEach((line) => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) return;

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    // Remove surrounding quotes if present
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  });

  return env;
}

/**
 * Resolves the DATABASE_URL from .env.test and logs a connection message.
 */
function resolveConnectionString() {
  const env = parseEnvFile(ENV_FILE);

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL is not defined in .env.test');
    process.exit(1);
  }

  console.log(`Resolved DATABASE_URL from ${path.basename(ENV_FILE)}`);
  console.log(`Connected successfully to: ${env.DATABASE_URL}\n`);

  return env.DATABASE_URL;
}

/**
 * Reads all .sql files from the ./migrations/ directory,
 * sorts them alphabetically (to ensure correct order),
 * and logs each filename that would be applied.
 */
function migrate() {
  // Resolve the database connection string
  const databaseUrl = resolveConnectionString();

  // Ensure the migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort them alphabetically
  const sqlFiles = files
    .filter((file) => path.extname(file).toLowerCase() === '.sql')
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  // Log each migration file in order
  sqlFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const sizeKB = (stats.size / 1024).toFixed(2);

    console.log(`  [${index + 1}] Applying: ${file} (${sizeKB} KB)`);
  });

  console.log('\nAll migrations logged successfully.');
}

migrate();

